/**
 *  @author      Jeremy Simon Thornton
 *  @copyright   2026 Jeremy Simon Thornton
 *  @brief       MEMLIB version macros and build-time version query.
 *  @details Generated by CMake from mem_version.h.in
 *  Edit the .in template, not this file.
 *  @note set the version in project() only.
 *
 *  The MEM_VERSION_* macros give the version of the headers a program was compiled against.
 *  NB mem_version() and mem_version_string() are compiled into MEM.LIB,
 *  so they give the version the library was built from.
 *
 * A mismatch means the headers and MEM.LIB are out of step:
 *
 * @code
 *  if (mem_version() != MEM_VERSION) {
 *      // headers and MEM.LIB out of step
 *  }
 * @endcode
 */
#ifndef MEM_VERSION_H
#define MEM_VERSION_H

#define MEM_VERSION_MAJOR  0
#define MEM_VERSION_MINOR  6
#define MEM_VERSION_PATCH  0

/**
 * single comparable value: 0xMMmm (major high byte, minor low byte)
 * matches the way DOS reports its own version (major in AH, minor in AL)
 */
#define MEM_VERSION        ((MEM_VERSION_MAJOR << 8) | MEM_VERSION_MINOR)

#define MEM_VERSION_STRING "0.6.0"

/**
* @brief   Version of MEM.LIB as built.
*
* Packed as 0xMMmm: major in the high byte, minor in the low byte.
* Compare with the MEM_VERSION macro to detect a header/library mismatch.
*/
unsigned int mem_version();

/**
* @brief   Full version string of MEM.LIB as built, e.g. "1.2.3".
*
* Includes the patch number, which mem_version() omits.
*/
const char* mem_version_string();

#endif
